<section class="page-heading"><div><p class="eyebrow">DES COMBINAISONS À PARTIR DE VOTRE GARDE-ROBE</p><h1>Suggestions de tenues</h1><p class="subheading">Règles locales : pièces disponibles, catégories complémentaires et rotation des pièces peu portées.</p></div><a class="button secondary" href="<?= e(url('generator',$filters)) ?>">↻ Autres propositions</a></section>
<form class="filter-bar generator-filters" method="get"><input type="hidden" name="page" value="generator"><input name="occasion" value="<?= e($filters['occasion']) ?>" placeholder="Occasion"><input name="style" value="<?= e($filters['style']) ?>" placeholder="Style"><input name="season" value="<?= e($filters['season']) ?>" placeholder="Saison"><input name="color" value="<?= e($filters['dominant']) ?>" placeholder="Couleur dominante"><select name="formality"><option value="">Formalite indifferente</option><?php foreach(['casual'=>'Decontracte','smart_casual'=>'Decontracte chic','formal'=>'Formel','black_tie'=>'Tenue de soiree'] as $key=>$label): ?><option value="<?= e($key) ?>" <?= ($filters['formality']??'')===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select><button class="button secondary">Générer</button></form>
<?php if(!$proposals): ?><div class="empty-state"><h3>Pas assez de pièces disponibles pour proposer une tenue</h3><p>Ajoutez des pièces ou rendez-en disponibles dans la gestion du linge.</p><a class="button primary" href="<?= e(url('clothes-create')) ?>">Ajouter une pièce</a></div><?php else: ?><div class="suggestion-grid"><?php foreach($proposals as $index=>$proposal): ?><article class="suggestion-card"><div class="suggestion-heading"><span>PROPOSITION 0<?= e($index+1) ?></span><b><?= count($proposal['items']) ?> pièces</b></div><div class="suggestion-items"><?php foreach($proposal['items'] as $item): ?><a href="<?= e(url('clothes-show',['id'=>$item['id']])) ?>" class="suggestion-item"><div><?php if($item['image_path']): ?><img src="<?= e(APP_BASE_URL.'/'.$item['image_path']) ?>" alt=""><?php else: ?><span>G</span><?php endif; ?></div><small><?= e($item['label_name']) ?></small><b><?= e($item['name']) ?></b></a><?php endforeach; ?></div><form method="post" action="<?= e(url('generator-save')) ?>" class="suggestion-save"><?= csrf_field() ?><input name="name" value="Suggestion <?= e($index+1) ?>" aria-label="Nom de la tenue"><?php foreach($proposal['ids'] as $id): ?><input type="hidden" name="items[]" value="<?= e($id) ?>"><?php endforeach; ?><button class="button primary">Enregistrer cette tenue <span>→</span></button></form></article><?php endforeach; ?></div><?php endif; ?>
